<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\DriverService;use App\Support\Url;Auth::requirePermission('CARRIER_DRIVER_VIEW');$rows=DriverService::allOwn();$pageTitle='My Drivers';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>My drivers</h1><p>Carrier-created, Operations-verified Driver profiles.</p></div><?php if(Auth::can('CARRIER_DRIVER_CREATE')):?><a class="button" href="<?=h(Url::to('carrier/drivers/create.php'))?>">Create Driver</a><?php endif;?></div><div class="card table-wrap"><table><thead><tr><th>Driver</th><th>Licence</th><th>Medical</th><th>Password setup</th><th>Verification</th><th>Engagement</th><th>Truck</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['display_name'])?></td><td><?=h($r['licence_number'].' · '.$r['licence_expiry'])?></td><td><?=h($r['medical_result'].' · '.$r['medical_expiry'])?></td><td><?=h($r['setup_used_at']?'Completed':'Pending')?></td><td><span class="status-pill"><?=h($r['verification_status'])?></span></td><td><?=h(str_replace('_',' ',$r['engagement_status']))?></td><td><?=h($r['registration_number']?:'Not linked')?></td><td><a href="<?=h(Url::to('carrier/drivers/view.php?id='.$r['driver_id']))?>">View</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8" class="muted">No Drivers created.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
